create extension if not exists pgcrypto;
create type public.member_role as enum ('waiter','manager','supplier');
create type public.sale_status as enum ('pending','approved','rejected');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, kind text not null check (kind in ('restaurant','supplier')), created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', preferred_language text not null default 'en' check (preferred_language in ('en','ru','ka')), created_at timestamptz not null default now());
create table public.memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null, created_at timestamptz not null default now(), unique (organization_id,user_id,role));
create table public.wine_offers (id uuid primary key default gen_random_uuid(), supplier_organization_id uuid not null references public.organizations(id), name text not null, producer text not null, region text not null default '', menu_price numeric(10,2) not null check (menu_price >= 0), waiter_bonus numeric(10,2) not null check (waiter_bonus >= 0), bonus_fund numeric(12,2) not null default 0 check (bonus_fund >= 0), active boolean not null default true, created_at timestamptz not null default now());
create table public.restaurant_offers (id uuid primary key default gen_random_uuid(), restaurant_organization_id uuid not null references public.organizations(id) on delete cascade, wine_offer_id uuid not null references public.wine_offers(id) on delete cascade, active boolean not null default true, created_at timestamptz not null default now(), unique (restaurant_organization_id,wine_offer_id));
create table public.sales (id uuid primary key default gen_random_uuid(), restaurant_organization_id uuid not null references public.organizations(id), wine_offer_id uuid not null references public.wine_offers(id), waiter_user_id uuid not null references public.profiles(id), receipt_reference text not null, status public.sale_status not null default 'pending', bonus_amount numeric(10,2) not null check (bonus_amount >= 0), reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, created_at timestamptz not null default now(), unique (restaurant_organization_id,receipt_reference));
create table public.bonus_ledger (id uuid primary key default gen_random_uuid(), sale_id uuid not null unique references public.sales(id), waiter_user_id uuid not null references public.profiles(id), supplier_organization_id uuid not null references public.organizations(id), amount numeric(10,2) not null check (amount >= 0), entry_type text not null check (entry_type in ('earned','paid','reversed')), created_at timestamptz not null default now());
create index memberships_user_idx on public.memberships(user_id);
create index sales_restaurant_status_idx on public.sales(restaurant_organization_id,status);
create index sales_waiter_idx on public.sales(waiter_user_id);
create or replace function public.is_org_member(org_id uuid, allowed_roles public.member_role[] default null) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.memberships m where m.organization_id = org_id and m.user_id = auth.uid() and (allowed_roles is null or m.role = any(allowed_roles))); $$;
alter table public.organizations enable row level security;
alter table public.profiles enable row level security;
alter table public.memberships enable row level security;
alter table public.wine_offers enable row level security;
alter table public.restaurant_offers enable row level security;
alter table public.sales enable row level security;
alter table public.bonus_ledger enable row level security;
create policy "members can view their organizations" on public.organizations for select to authenticated using (public.is_org_member(id));
create policy "users can view own profile" on public.profiles for select to authenticated using (id = auth.uid());
create policy "users can update own profile" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy "members can view organization memberships" on public.memberships for select to authenticated using (public.is_org_member(organization_id));
create policy "supplier members manage own offers" on public.wine_offers for all to authenticated using (public.is_org_member(supplier_organization_id, array['supplier']::public.member_role[])) with check (public.is_org_member(supplier_organization_id, array['supplier']::public.member_role[]));
create policy "restaurant members view linked offers" on public.restaurant_offers for select to authenticated using (public.is_org_member(restaurant_organization_id, array['waiter','manager']::public.member_role[]) or exists (select 1 from public.wine_offers w where w.id = wine_offer_id and public.is_org_member(w.supplier_organization_id, array['supplier']::public.member_role[])));
create policy "restaurant managers manage offer links" on public.restaurant_offers for all to authenticated using (public.is_org_member(restaurant_organization_id, array['manager']::public.member_role[])) with check (public.is_org_member(restaurant_organization_id, array['manager']::public.member_role[]));
create policy "restaurant staff view sales" on public.sales for select to authenticated using (waiter_user_id = auth.uid() or public.is_org_member(restaurant_organization_id, array['manager']::public.member_role[]));
create policy "waiters submit own sales" on public.sales for insert to authenticated with check (waiter_user_id = auth.uid() and status = 'pending' and reviewed_by is null and reviewed_at is null and public.is_org_member(restaurant_organization_id, array['waiter']::public.member_role[]));
create policy "managers review sales" on public.sales for update to authenticated using (public.is_org_member(restaurant_organization_id, array['manager']::public.member_role[])) with check (public.is_org_member(restaurant_organization_id, array['manager']::public.member_role[]) and reviewed_by = auth.uid() and status in ('approved','rejected'));
create policy "users view own bonus ledger" on public.bonus_ledger for select to authenticated using (waiter_user_id = auth.uid() or public.is_org_member(supplier_organization_id, array['supplier']::public.member_role[]));
-- No client-side ledger writes. Approval and ledger posting must become one trusted atomic operation before live financial use.
